import java.util.Scanner;

public class Main {

	public static void main(String[] data) {
		Scanner total = new Scanner(System.in);
		int tempo = total.nextInt();
		int oneHundred = total.nextInt();
		int searchSize = 0;
		if (tempo == oneHundred) {
			searchSize = tempo;
		} else {
			searchSize = close(tempo, oneHundred, searchSize);
		}
		System.out.println(searchSize);
		total.close();
	}

	public static int close(int tempo, int oneHundred, int searchSize) {
		if (tempo < oneHundred) {
			int size = tempo;
			tempo = oneHundred;
			oneHundred = size;
		}
		tempo %= oneHundred;
		for (int mid = tempo; true; mid--) {
			if (tempo % mid == 0 && oneHundred % mid == 0) {
				searchSize = mid;
				break;
			}
		}
		return searchSize;
	}
}

