import java.util.Scanner;

public class Main {
	public static void main (String [] args) {
		Scanner Lsum = new Scanner (System.in);

		//２つの自然数入力
		int total_c = Lsum.nextInt();
		int answer = Lsum.nextInt();
		Lsum.close();

		int m;


		if ( total_c == answer) {
			m = total_c;
		} else {
			if (total_c > answer) {
				int master = total_c % answer;
				m = power(answer,master);
			}else {
				int master = answer % total_c;
				 m = power(total_c,master);
			}
		}

		System.out.println(m);

	}

	//最大公約数を求める
	public static int power(int total_c, int answer) {

		int master = Math.min(total_c, answer);

		for (int S = master; S >= 1; S--) {
			if (total_c % S == 0 && answer % S == 0) {
				return S;
			}
		}

		return 1;
	}
}

