public class Main {
	static Scanner max = new Scanner(System.in);
	public static void main(String[] args) {
		int result = max.nextInt();
		int kind = max.nextInt();
		System.out.println(order(result,kind));
	}
	//最大公約数gcdを求める
	static int order (int d, int b) {
		int answerR;
		while((answerR = d%b)!=0) {
			d = b;
			b = answerR;
		}
		return b;
	}
}

