class Main{
    //読み込みのテンプレ(stringオブジェクトまで)
    public static void main(String[] args) throws IOException{
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
        String strings = r.readLine();
        StringTokenizer currentCardPositionOfThePlayer = new StringTokenizer(strings," ");

        int length = Integer.parseInt((String)currentCardPositionOfThePlayer.nextElement());
        int money = Integer.parseInt((String)currentCardPositionOfThePlayer.nextElement());

        int counter = getGcd(length,money);
        System.out.println(counter);
    }

    public static int getGcd(int length,int money){

        int counter;

        if(length > money){

            while(length%money != 0 || money !=1){
                int total = length;
                int y_1 = money;
                length = money;
                money = total % money;

                if(money == 0){
                    money = y_1;
                    break;
                }
            }
            if(money == 1){
                counter = 1;
            }else{
                counter = money;
            }


        }else{
            int existCnt = length;
            int scn = money;

            length = scn;
            money = existCnt;

            while(length%money !=0 || money !=1){
                int total = length;
                int y_1 = money;
                length = money;
                money = total % money;
                if(money == 0){
                    money = y_1;
                    break;
                }
            }
            if(money == 1){
                counter = 1;
            }else{
                counter = money;
            }

        }
        return counter;
    }
}

/**
 * ３つの整数a, b, cを読み込み、それらが a < b < cの条件を満たすならば"Yes"を、
 * 満たさないならば"No"を出力するプログラム
 * @author 前島佑介
 *@version 2014/12/1
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;


// 2-A ３つの整数a, b, cを読み込み、それらが a < b < cの条件を満たすならば"Yes"を、
//満たさないならば"No"を出力するプログラム
class Main {

	// プログラムのエントリポイント
	public static void main(String[] args) {

		//入力値1つ目
		int intervalValue = 0;

		//入力値2つ目
		int intNum2 = 0;

		//入力値2つ目
		int intNum3 = 0;

		try{
			//キーボードからの入力準備
			BufferedReader r = new BufferedReader(new InputStreamReader(System.in));

			//キーボードからの入力をString型で受け取る
			String line = r.readLine();

			//文字列の分割:入力値を" "で分ける
			//分けた文字列はstrLineAry[0]とstrLineAry[1]に分けられる
			String[] strLineAry = line.split(" ");

			//入力値の１つ目の値
			intervalValue = Integer.parseInt(strLineAry[0]);

			//２つ目の値
			intNum2 = Integer.parseInt(strLineAry[1]);

			//３つ目の値
			intNum3 = Integer.parseInt(strLineAry[2]);

			if(intervalValue < intNum2 && intNum2 < intNum3) {
				System.out.println("Yes");
			}else{
				System.out.println("No");
			}



			//例外処理
			}catch(IOException e) {

				//例外時の出力
				System.out.println(e);

			}catch(NumberFormatException e) {

				//数値以外の入力値で出力
				System.out.println("数値で入力して下さい");
			}
	}
}

