public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader inputP = new BufferedReader(new InputStreamReader(System.in));
        String req[];
        int interval,light,waCounter;
        StringBuilder tmp = new StringBuilder();
        while(true){
            req = inputP.readLine().split(" ");
            interval = Integer.parseInt(req[0]);
            light = Integer.parseInt(req[1]);
            if(interval==0 && light==0) break;
            waCounter = 0;
            for(int i=1;i<=interval-2;i++){
                for(int op=i+1;op<=interval-1;op++){
                    int inputHPAndCountData = light - i - op;
                    if(op < inputHPAndCountData && inputHPAndCountData <= interval) waCounter++;
                }
            }
            tmp.append(waCounter).append("\n");
        }
        System.out.print(tmp);
    }
}

