public class Main {
	public static void solve(int gcd, int s) {
		int sc = 0;
		for(int array=1;array<=gcd-2;array++) {
			for(int result=array+1;result<=gcd-1;result++) {
				for(int val=result+1;val<=gcd;val++) {
					if(array+result+val==s) sc++;
				}
			}
		}
		System.out.println(sc);
	}
