	public static int gcd(int scanner,int cards){
		int res=0;
		for(int minAbs=0;minAbs<scanner;minAbs++){
			for(int distanceBase=0;distanceBase<minAbs;distanceBase++){
				for(int flooredDistance=0;flooredDistance<distanceBase;flooredDistance++){
					if(cards-3==minAbs+distanceBase+flooredDistance){
						res=res+1;
					}
				}
			}
		}
		return res;
	}
