/**
n×m  の行列 A  と m×l  の行列 B  を入力し、それらの積である n×l  の
 を出力するプログラムを作成してください。行列 C  の各要素 c ij   は次の式で得られます：

 １行目に n 、m 、l  が空白区切りで与えられます。

続く行に n×m  の行列 A  と m×l  の行列 B  が与えられます。

 */

//スキャナつかうため

import java.util.Scanner;

public class Main {
	// プログラムのエントリポイント
	public static void main(String[] args) {
		// 入力ストリームの生成
		Scanner scan = new Scanner(System.in);
		// 3つの数値を受け取る
		int interestAmount = scan.nextInt();
		int intervalValue = scan.nextInt();
		int intL = scan.nextInt();
		// 受け取った数値で配列をつくる
		// Aの行列
		int[][] differences = new int[interestAmount][intervalValue];
		// Bの行列
		int[][] console = new int[intervalValue][intL];
		// Cの行列
		long[][] gyouc = new long[interestAmount][intL];
		// 数値をAの配列の数受け取る
		for (int mid = 0; mid < interestAmount; mid++) {
			for (int mozi_length = 0; mozi_length < intervalValue; mozi_length++) {
				differences[mid][mozi_length] = scan.nextInt();
			}
		}
		// Bの配列の数数値を受け取る
		for (int mid = 0; mid < intervalValue; mid++) {
			for (int mozi_length = 0; mozi_length < intL; mozi_length++) {
				console[mid][mozi_length] = scan.nextInt();
			}
		}
		// 計算
		for (int mid = 0; mid < interestAmount; mid++) {
			for (int mozi_length = 0; mozi_length < intL; mozi_length++) {

				for (int mark = 0; mark < intervalValue; mark++) {
					// Cの配列に計算結果を入れていく
					gyouc[mid][mozi_length] += differences[mid][mark] * console[mark][mozi_length];
				}
				System.out.print(gyouc[mid][mozi_length]);
				if (mozi_length != intL - 1) {
					// 空白
					System.out.print(" ");
				}
			}
			// 改行
			System.out.println();
		}

	}
}

