class execute {
   private final BufferedReader rev;
   private StringTokenizer ans;

    execute(InputStream regex) {
        rev = new BufferedReader(new InputStreamReader(regex));
    }

    String nextString() {
        while (ans == null || !ans.hasMoreTokens()) {
            try {
                ans = new StringTokenizer(rev.readLine());
            } catch (IOException mr) {
                throw new RuntimeException(mr);
            }
        }
        return ans.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(nextString());
    }

    long nextLong() {
        return Long.parseLong(nextString());
    }

    double nextDouble() {
        return Double.parseDouble(nextString());
    }



    ArrayList<Integer> LongArr(int count) {
        ArrayList<Integer> array = new ArrayList<>();
        for (int numChars = 0; numChars < count; numChars++) {
            int filter = nextInt();
            array.add(filter);
        }
        return array;
    }

    int[] nextIntArray(int count) {
        int[] array = new int[count];
        for (int numChars = 0; numChars < count; numChars++) {
            array[numChars] = nextInt();
        }
        return array;
    }
}

