        int totalButton;

        if(hit < oneHundred) {
            totalButton = hit;
            hit = oneHundred;
            oneHundred = totalButton;
        }
        while(oneHundred > 0){
            totalButton = hit % oneHundred;
            hit = oneHundred;
            oneHundred = totalButton;
        }
        return hit;
    }
