	public static int getRange(int ans, int buff1){
		int[] orderedArray = {ans, buff1};
		int x;
        int arrayPoint;
        if (orderedArray[0] > orderedArray[1]) {
            x = orderedArray[0];
            arrayPoint = orderedArray[1];
        } else {
            x = orderedArray[1];
            arrayPoint = orderedArray[0];
        }

        // ここからがユークリッドの互除法を用いた最大公約数を
        // 求める為の式
        int list;
        while ((list = x % arrayPoint) != 0) {
            x = arrayPoint;
            arrayPoint = list;
		}

		return arrayPoint;
	}

}

