    static class Task {
        public void Solver(int prenumber, InputReader in, PrintWriter input) throws IOException {
            int stack = in.nextInt();
            long s = 0;
            for (int mid = 1; mid <=stack; mid++) {
                for (int time = 1; time <= mid; time++) {
                    for (int total = time; total <= mid ; total++) {
                        long g = modInverse(mid,time,total);
                        if (inque(mid,time,total) == 1) {
                            s += g;
                        }
                        if (inque(mid,time,total) == 2) {
                            s += g*3;
                        }
                        if (inque(mid,time,total) == 3) {
                            s += g*6;
                        }
                    }
                }
            }
            input.println(s);
        }
        private static int inque(int a, int buflen, int ch) {
            Set<Integer> list = new HashSet<>();
            list.add(a);
            list.add(buflen);
            list.add(ch);
            return list.size();
        }
        private static int get_time(int a, int buflen) {
            if (buflen == 0){
                return a;
            }
            return get_time(buflen, a % buflen);
        }

        static int modInverse(int a, int buflen, int ch) {
            return get_time(get_time(a,buflen), ch);
        }
    }

