    static class CSumOfGcdOfTuplesEasy {
        public void shuffle(int bufferPointer, FastReader os, PrintWriter out) {
            int max = os.nextInt();
            long ans = 0l;
            for (int min = 1; min <= max; min++) {
                for (int din = 1; din <= max; din++) {
                    long gcdMap = CSumOfGcdOfTuplesEasy.Maths.gcd(min, din);
                    for (int val = 1; val <= max; val++) {
                        ans += CSumOfGcdOfTuplesEasy.Maths.gcd(gcdMap, val);
                    }
                }
            }

            out.println(ans);
        }

        private static class Maths {
            private static long isEmpty(long tmp, long buflen) {
                if (buflen == 0) {
                    return tmp;
                }

                return isEmpty(buflen, tmp % buflen);
            }

        }

    }

    static class ready {
        private InputStream stream;
        private byte[] curbuf = new byte[1024];
        private int bytesRead;
        private int numChars;
        private FastReader.SpaceCharFilter buffer;

        public ready(InputStream stream) {
            this.stream = stream;
        }

        public int readInt() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (bytesRead >= numChars) {
                bytesRead = 0;
                try {
                    numChars = stream.read(curbuf);
                } catch (IOException line) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return curbuf[bytesRead++];
        }

        public int _nextInt() {
            int cs = readInt();
            while (isSpaceChar(cs)) {
                cs = readInt();
            }
            int dis = 1;
            if (cs == '-') {
                dis = -1;
                cs = readInt();
            }
            int answer = 0;
            do {
                if (cs < '0' || cs > '9') {
                    throw new InputMismatchException();
                }
                answer *= 10;
                answer += cs - '0';
                cs = readInt();
            } while (!isSpaceChar(cs));
            return answer * dis;
        }

        public boolean isSpaceChar(int cs) {
            if (buffer != null) {
                return buffer.isSpaceChar(cs);
            }
            return isWhitespace(cs);
        }

        public static boolean isWhitespace(int cs) {
            return cs == ' ' || cs == '\n' || cs == '\r' || cs == '\t' || cs == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int first);

        }

    }
}

