public class selectionSort {
	int set;
	long total = 0L;

	public static void main(String[] args) throws IOException {
		InputStreamReader r = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(r);
		Main intData = new Main(in);
		intData.calc();
		intData.showResult();
	}

	selectionSort(BufferedReader in) throws IOException {
		String[] token = in.readLine().split(" ");
		set = Integer.parseInt(token[0]);
	}

	void calc() {
		for (int ans = 1; ans <= set; ++ans) {
			for (int strData = 1; strData <= set; ++strData) {
				for (int col = 1; col <= set; ++col) {
					int test = rd(ans, strData);
					int rd = rd(col, test);
					total += rd;
				}
			}
		}
	}

	void show() {
		System.out.println(total);
	}

	int rd(int row, int max) {
		if (row < max) {
			return rd(max, row);
		}
		if (row % max == 0) {
			return max;
		}
		return rd(max, row % max);
	}
}

