public class Main {
    public static void main(String[] args) throws Exception {
        Scanner scn = new Scanner(System.in);
        int keyboard = scn.nextInt();
        long sum2 = 0;

        for(int ans2 = 1; ans2 <= keyboard; ans2++)
        {
            for(int bt = 1; bt <= keyboard; bt++)
            {
                for(int cal = 1; cal <= keyboard; cal++)
                {
                    if(ans2 == bt && bt ==cal)
                    {
                        sum2 += ans2;
                    }
                    else
                    {
                        //最大公約数を求める
                        int search = find(ans2,bt,cal);
                        sum2 += search;
                    }
                }
            }
        }
        System.out.println(sum2);
    }

    public static int find(int maxCount,int rate, int proX) {
        if(maxCount < rate)
        {
            int search = maxCount;
            maxCount = rate;
            rate = search;
        }
        int scanner = 0;
        while(( scanner = maxCount % rate) != 0)
        {
            maxCount = rate;
            rate = scanner;
        }

        if(rate < proX)
        {
            int search = rate;
            rate = proX;
            proX = search;
        }
        while((scanner = rate % proX) != 0)
        {
            rate = proX;
            proX = scanner;
        }
        return proX;
    }
}

