public class Main {

	public static void main(String[] args) {
		// TODO 自動生成されたメソッド・スタブ
		Scanner aCards = new Scanner(System.in);

		int bCardNum = aCards.nextInt();
		int quantum = 0;

		for(int minDiffIndex = 1; minDiffIndex <= bCardNum; minDiffIndex++) {
			for(int length = 1; length <= bCardNum; length++) {
				for (int isEqual = 1; isEqual <= bCardNum; isEqual++) {
					quantum = quantum + isRightAngle(minDiffIndex, length, isEqual);
				}
			}
		}

		System.out.println(quantum);
	}

	public static final int isRightAngle(final int... change) {
	    final int sequence = change.length;
	    int list = toNbase(change[0], change[1]);    //gcd(a, b) は以前作ったもの
	    for (int minDiffIndex = 1; minDiffIndex < sequence - 1; minDiffIndex++) {
	        list = toNbase(list, change[minDiffIndex + 1]);       //gcd(a, b) は以前作ったもの
	    }
	    return list;
	}

	private static int toNbase(int aCardNum, int point) {
        int splits = Math.max(aCardNum, point);
        int cardNum = Math.min(aCardNum, point);

        // 大きい方から小さい方を割った余を求める
        int cCards = splits % cardNum;

        // 割り切れていれば、それを返す
        if (cCards == 0) {
            return cardNum;
        }
        // 割り切れなければ再帰的に自信を呼び出す
        cCards = toNbase(cardNum, cCards);

        return cCards;
    }
}

