class Scanner
{
    StringTokenizer stack;
    BufferedReader line;

    public Scanner(InputStream time){	line = new BufferedReader(new InputStreamReader(time));}

    public String next() throws IOException
    {
        while (stack == null || !stack.hasMoreTokens())
            stack = new StringTokenizer(line.readLine());
        return stack.nextToken();
    }

    public int Reader() throws IOException {return Integer.parseInt(next());}

    public long exec() throws IOException {return Long.parseLong(next());}

    public String nextLine() throws IOException {return line.readLine();}

    public double FastReader() throws IOException
    {
        String proc = next();
        StringBuilder gcd = new StringBuilder("0");
        double target = 0, gen = 1;
        boolean tok = false, rep = false;
        int col = 0;
        if(proc.charAt(0) == '-')
        {
            rep = true;
            col++;
        }
        for(int max = col; max < proc.length(); max++)
            if(proc.charAt(max) == '.')
            {
                target = Long.parseLong(gcd.toString());
                gcd = new StringBuilder("0");
                tok = true;
            }
            else
            {
                gcd.append(proc.charAt(max));
                if(tok)
                    gen *= 10;
            }
        target += Long.parseLong(gcd.toString()) / gen;
        return target * (rep?-1:1);
    }

    public boolean OutputWriter() throws IOException {return line.ready();}


}

