class FastScanner {
    private final InputStream in = System.in;
    private final byte[] str = new byte[1024];
    private int kint = 0;
    private int debugDataPath = 0;
    private boolean readLong() {
        if (kint < debugDataPath) {
            return true;
        }else{
            kint = 0;
            try {
                debugDataPath = in.read(str);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (debugDataPath <= 0) {
                return false;
            }
        }
        return true;
    }

    private int skipUnprintable() { if (readLong()) return str[kint++]; else return -1;}
    private static boolean longgcd(int toBuffers) { return 33 <= toBuffers && toBuffers <= 126;}
    public boolean myconv() { while(readLong() && !longgcd(str[kint])) kint++; return readLong();}
    public String nextCharArray() {
        if (!myconv()) throw new NoSuchElementException();
        StringBuilder len = new StringBuilder();
        int first = skipUnprintable();
        while(longgcd(first)) {
            len.appendCodePoint(first);
            first = skipUnprintable();
        }
        return len.toString();
    }
    public long nextLong() {
        if (!myconv()) throw new NoSuchElementException();
        long r = 0;
        boolean max = false;
        int first = skipUnprintable();
        if (first == '-') {
            max = true;
            first = skipUnprintable();
        }
        if (first < '0' || '9' < first) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= first && first <= '9') {
                r *= 10;
                r += first - '0';
            }else if(first == -1 || !longgcd(first)){
                return max ? -r : r;
            }else{
                throw new NumberFormatException();
            }
            first = skipUnprintable();
        }
    }
    public int nextInt() {
        long timer = nextLong();
        if (timer < Integer.MIN_VALUE || timer > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) timer;
    }
    public double nextDouble() { return Double.parseDouble(nextCharArray());}
}

