            r = null;
        }

        public String nextIntArrayOneBased() {
            while (r == null || !r.hasMoreTokens()) {
                try {
                    r = new StringTokenizer(bufPointer.readLine());
                } catch (IOException buflen) {
                    throw new RuntimeException(buflen);
                }
            }
            return r.nextToken();
        }

        public int nextLongArrayOneBased() {
            return Integer.parseInt(nextIntArrayOneBased());
        }

    }
}

