    static PrintWriter ret = new PrintWriter(outputStream);

    public static void main(String[] args) {
        int line = in.NI();
        String total_time = in.next();
        StringBuilder stack = new StringBuilder();
        for (int hs=0;hs<total_time.length();hs++) {
            char objects = total_time.charAt(hs);
            for (int init_time=0;init_time<line;init_time++) {
                if (objects == 'Z'){
                    objects= 'A';
                } else {
                    objects++;
                }
            }
            stack.append(objects);
        }
        ret.println(stack.toString());
        ret.close();
    }

    static class FastScanner {
        public BufferedReader context;
        public StringTokenizer testNumber;

        public FastScanner(InputStream stream) {
            context = new BufferedReader(new InputStreamReader(stream), 32768);
            testNumber = null;
        }

        public String nextIntArrayDec() {
            while (testNumber == null || !testNumber.hasMoreTokens()) {
                try {
                    testNumber = new StringTokenizer(context.readLine());
                } catch (IOException parent) {
                    throw new RuntimeException(parent);
                }
            }
            return testNumber.nextToken();
        }

        public int m() {
            return Integer.parseInt(nextIntArrayDec());
        }

        public long sn() {
            return Long.parseLong(nextIntArrayDec());
        }

    }


}

