import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sum2 = new Scanner(System.in);
        int hanako_point = Integer.parseInt(sum2.next());
        long answerL = Long.parseLong(sum2.next());
        int sn = Integer.parseInt(sum2.next());

        int[] rsum = new int[sn];
        for (int Ci = 0; Ci < sn; Ci++) {
            rsum[Ci] = Integer.parseInt(sum2.next());
        }

        // 合っている人のみ抽出
        int[] pre = new int[hanako_point];
        for (int Ci = 0; Ci < sn; Ci++) {
            int count_Empty = rsum[Ci];
            pre[count_Empty - 1]++;
        }

        // 最大点数で初期化
        long[] change = new long[hanako_point];
        for (int Ci = 0; Ci < hanako_point; Ci++) {
            change[Ci] = answerL;
        }

        // 合ってるポイント分減算して減らす
        for (int Ci = 0; Ci < hanako_point; Ci++) {
            int checklist = pre[Ci];
            int matrix_B = sn - checklist;

            change[Ci] -= matrix_B;
        }

        for (int Ci = 0; Ci < hanako_point; Ci++) {
            System.out.println(change[Ci] > 0 ? "Yes" : "No");
        }
    }
}

