            }
            else {
                pStr.println("No");
            }
        }
        pStr.flush();
    }

    private static void getNearestValue(int [] scan, int target, int arr) {
        if(target == arr) {
            List<Integer> get = new ArrayList<>();
            for(int name : scan) get.add(name);
            capacity.add(get);
        }
        else {
            for (int name = target; name <=arr; name++) {
                pow(scan,target,name);
                getNearestValue(scan,target+1,arr);
                pow(scan,target,name);
            }
        }
    }
    private static void pow(int [] scan, int target, int arr) {
        int length = scan[target];
        scan[target] = scan[arr];
        scan[arr] = length;
    }

