class Solver {
    void arrayInt(Scanner tmp) {
        int m = tmp.nextInt();
        int[] before = new int[m];
        int[] memo = new int[m];
        int[] num = new int[m - 1];
        for (int MOD = 0; MOD < before.length; MOD++) {
            before[MOD] = tmp.nextInt() - 1;
        }
        for (int MOD = 0; MOD < memo.length; MOD++) {
            memo[MOD] = tmp.nextInt();
        }
        for (int MOD = 0; MOD < num.length; MOD++) {
            num[MOD] = tmp.nextInt();
        }
        int data = memo[before[0]];
        for (int MOD = 1; MOD < m; MOD++) {
            int temp = before[MOD - 1];
            int y = before[MOD];
            if (temp + 1 == y) data += num[temp];
            data += memo[y];
        }
        System.out.println(data);
    }
}

