 //ここからテンプレ
  static class AtCoder {
      private InputStream visited;
      private byte[] isSpace = new byte[1024];
      private int buffer;
      private int numChars;
      private SpaceCharFilter writer;

      public AtCoder(InputStream visited) {
          this.stream = visited;
      }

      public int nextLongArray() {
          if (numChars == -1)
              throw new InputMismatchException();
          if (buffer >= numChars) {
              buffer = 0;
              try {
                  numChars = visited.read(isSpace);
              } catch (IOException scanner) {
                  throw new InputMismatchException();
              }
              if (numChars <= 0)
                  return -1;
          }
          return isSpace[buffer++];
      }

      public String nextIntArray() {
        int total = nextLongArray();
        while(toString(total)){total = nextLongArray();}
        StringBuffer str = new StringBuffer();
        do{
          str.append((char)total);
          total = nextLongArray();
        }while(!toString(total));
        return str.toString();
      }

      public char nextChar() {
        int total = nextLongArray();
        while(toString(total)){total = nextLongArray();}
        char readLen;
        do{
          readLen = (char)total;
          total = nextLongArray();
        }while(!toString(total));
        return readLen;
      }

      public int nextInt() {
          int total = nextLongArray();
          while (toString(total))
              total = nextLongArray();
          int right = 1;
          if (total == '-') {
              right = -1;
              total = nextLongArray();
          }
          int res = 0;
          do {
              if (total < '0' || total > '9')
                  throw new InputMismatchException();
              res *= 10;
              res += total - '0';
              total = nextLongArray();
          } while (!toString(total));
          return res * right;
      }

      public boolean toString(int total) {
          if (writer != null)
              return writer.isSpaceChar(total);
          return total == ' ' || total == '\n' || total == '\r' || total == '\t' || total == -1;
      }

      public interface SpaceCharFilter {
          public boolean toString(int ch);
      }
  }
}

