public class Main {
    static ArrayList<trip> dist;
    public static void main(String[] args){
        try{
            BufferedReader fr=new BufferedReader(new InputStreamReader(System.in));
            String[] stack=fr.readLine().split(" ");
            int n=Integer.parseInt(stack[0]);
            int calcF=Integer.parseInt(stack[1]);
            stack=fr.readLine().split(" ");
            int[] arr=new int[n];
            int sum_c=0;
            int cost2=0;
            for(int s_i=0;s_i<n;s_i++){
                arr[s_i]=Integer.parseInt(stack[s_i]);
                sum_c+=arr[s_i];
                if(sum_c<=calcF){
                    cost2++;
                }
            }
            System.out.println(cost2+1);

        }catch(Exception line){
            System.out.println("KKKK "+line.getMessage());
        }
    }

    static class hashCode{
        int currentHeights,index,child;
        public hashCode(int currentHeights,int index,int child){
            this.lev=currentHeights;
            this.node=index;
            this.child=child;
        }
    }
    static void showResult(ArrayList<ArrayList<Integer>> set){
        Queue<trip> val=new ArrayDeque<>();
        val.add(new trip(0,0,set.get(0).size()));
        boolean[] brr=new boolean[set.size()];
        brr[0]=true;
        while(val.size()>0){
            trip cost=val.poll();
            if(cost.child==0) {
                dist.add(cost);
            }

            int index=cost.node;
            for(int s_i=0;s_i<set.get(index).size();s_i++){
                int debugDataPath=set.get(index).get(s_i);
                if(!brr[debugDataPath]){
                    val.add(new trip(cost.lev+1,debugDataPath,set.get(debugDataPath).size()));
                    brr[debugDataPath]=true;
                }
            }
        }
    }
    static void parseInts(int[] acs) {
        Random parent = new Random();
        for (int s_i = 0; s_i < acs.length; s_i++) {
            int scanner = parent.nextInt(acs.length);
            int isDigit = acs[s_i];
            acs[s_i] = acs[scanner];
            acs[scanner] = isDigit;
        }
    }
}

