import java.util.*;
public class Main{
    public static void main(String[] args){
      Scanner ans = new Scanner(System.in);
      int Array = ans.nextInt();
      int taro = ans.nextInt();
      int[] landCt = new int[taro];
      int[] dp = new int[Array+3];
      Set<Integer> currPos = new HashSet<Integer>();
      for(int S = 0;S < taro;S++){
        landCt[S] = ans.nextInt();
        currPos.add(landCt[S]);
      }
      dp[0] = 0;
      if(currPos.contains(1)){
        dp[1]=0;
      }else dp[1]=1;
      if(currPos.contains(2)){
      	dp[2]=0;
      }else dp[2] = dp[1]+1;
      for(int S = 3;S <= Array;S++){
      	if(currPos.contains(S)) dp[S]=0;
        else dp[S]=(dp[S-1]+dp[S-2])%1000000007;
      }
      System.out.println(dp[Array]);
    }
    public static int run(int list, int point){
      return list*point/calc(list,point);
    }
    public static int calc(int list, int point){
      if(list < point)return calc(point,list);
      if(point==0)return list;
      return calc(point,list%point);
