    public static void main(String[] args) throws Exception {
        // Your code here!
        Scanner scan = new Scanner(System.in);

        int nowT = scan.nextInt();
        int stdin = scan.nextInt();
        int[] search = new int[stdin];
        for (int sam = 0; sam < stdin; sam++) {
            search[sam] = scan.nextInt();

            if (sam > 0 && search[sam] - search[sam - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int total = 0;
        long cnt = 1;

        for (int sam = 0; sam < stdin; sam++) {
            int numberCount = search[sam];
            cnt = cnt * mincost((numberCount - 1) - total) % more;
            total = numberCount + 1;
        }

        cnt = cnt * mincost(nowT - total) % more;

        System.out.println(cnt);
    }

    public static long mincost(long nowT) {
        long num1 = 1;
        long num2 = 1;
        long dist = 1;

        for (long sam = 1; sam < nowT; sam++) {
            dist = (num1 + num2) % more;
            num1 = num2;
            num2 = dist;
        }

        return dist;
    }
}

