class getNearestValue {
    public static int[] distance;
    public getNearestValue (int start) {
        distance = new int[start];
        for(int min = 0; min < start; min++)distance[min] = -1;
    }

    public int search(int remove) {
        if(distance[remove] != -1)return distance[remove];
        if(remove == 0) distance[remove] = 1;
        else if(remove == 1) distance[remove] = 1;
        else distance[remove] = search(remove-1) + search(remove-2);
        while(distance[remove] >= Mod.mod) distance[remove] -= Mod.mod;
        return distance[remove];
    }
}

