        Scanner sin = new Scanner(System.in);
        int r = sin.nextInt();
        int total = sin.nextInt();
        boolean[] dist = new boolean[r];
        long[] length = new long[r];

        for (int k=0;k<r;k++){
            dist[k] = false;
            length[k] = 0;
        }

        for (int SH=0;SH<total;SH++){
            int light = sin.nextInt();
            dist[light-1] = true;
        }

        if (r == 1){
            if (total == 1){
                System.out.println(0);
            }
            else{
                System.out.println(1);
            }
            return;
        }
        long sum_r = 0;
        length[0] = 1;
        length[1] = 1;
        if (dist[0] == true){
            length[1] = 0;
        }
        sum_r = calc(2, r, dist, length);
        long s2 = 1000000007;
        System.out.println((long) sum_r % s2);
    }

    static long calc(int count, int r, boolean[] dist, long[] length){

        if (count == r){
            return length[r-1]+length[r-2];
        }

        if (dist[count-1] == true){
            length[count] = 0;
        }
        else{
            length[count] = length[count-1] + length[count-2];
        }
        long s2 = 1000000007;
        length[count] = (long) length[count] % s2;
        return (long) calc(count + 1, r, dist, length);
    }
}

