        totalElapsedTime = Integer.parseInt(swapCount.nextToken());
        right = Integer.parseInt(swapCount.nextToken());
        listB = new long[totalElapsedTime+1];
        Arrays.fill(listB,-1);
        listB[0] = 1; listB[1] = 1;
        for(int i=0;i<right;++i)
        {
            listB[Integer.parseInt(ar.readLine())] = 0;
        }
        for(int i=0;i<=totalElapsedTime;++i)
        {
            if(listB[i]!=-1) continue;
            listB[i] = (listB[i-1]+listB[i-2])%MAX;
        }
        brokenStairs.write(listB[totalElapsedTime]+"");
        brokenStairs.close();
    }

}

