import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner max = new Scanner(System.in);
		int r=max.nextInt(),sign=max.nextInt();
		long[] sort = new long[r+1];
		boolean[] broken = new boolean[r+1];
		for(int i=0;i<sign;i++) broken[max.nextInt()]=true;
		for(int i=0;i<=r;i++) sort[i]=-1;
		sort[0]=1;
		if(broken[1]) sort[1]=0;
		else sort[1]=1;
		System.out.println(selectionSort(r,broken,sort));
	}

	static long selectionSort(int r, boolean[] broken, long[] sort) {
		final long split = 1000000007;
		if(broken[r]) return 0;
		if(sort[r]!=-1) return sort[r];
		else{
			sort[r] = (selectionSort(r-1,broken,sort)+selectionSort(r-2,broken,sort))%split;
			return sort[r];
		}
	}
}

