import java.io.PrintStream;
import java.util.Scanner;

public class Main {
    static final Scanner     times = new Scanner(System.in);
    static final PrintStream max = System.out;
    static int mod = (int)1E9 + 7;
    public static void main(String[] args) {
        int r = printlnArray();
        long[] set = new long[r+1];
        set[0] = 1;
        set[1] = 1;
        for (int minIndex = 2; minIndex <= r; minIndex++) {
            set[minIndex] = set[minIndex-1] + set[minIndex-2];
            set[minIndex] %= mod;
        }

        int stack = printlnArray();
        if (stack == 0) {
            max.println(set[r]);
            return;
        }

        int[] add = new int[stack + 2];
        for (int minIndex = 1; minIndex <= stack; minIndex++) {
            add[minIndex] = printlnArray();
        }
        add[stack+1] = r+1;
        long arg = set[add[1]-1];

        for (int minIndex = 2; minIndex <= stack+1; minIndex++) {
            int diff = add[minIndex] - add[minIndex-1] - 2;
            if (diff < 0) {
                max.println(0);
                return;
            }

            arg *= set[diff];
            arg %= mod;
        }
        max.println(arg);
    }


    static int run(int stack, int r) {
        if(stack < r) return run(r, stack);
        if(r == 0) return stack;
        return run(r, stack % r);
    }

    static long lcm(int stack, int r) {
        return (long) stack * r / run(stack, r);
    }

    private static long arrayDouble() {
        return times.nextLong();
    }

    private static int printlnArray() {
        return times.nextInt();
    }

    private static String findNextPermutation() {
