    }

    private static long[] nlongs(int r, int res1) {
        long[] add = new long[res1 + r];
        for (int minIndex = 0; minIndex < r; minIndex++)
            add[res1 + minIndex] = arrayDouble();
        return add;
    }

    private static int[] Pair(int r, int res1) {
        int[] add = new int[res1 + r];
        for (int minIndex = 0; minIndex < r; minIndex++)
            add[res1 + minIndex] = printlnArray();
        return add;
    }
}

