public class Main {
	public static void main(String[] args) {
		Scanner cost2 = new Scanner(System.in);
		int free = cost2.nextInt();
		int[] chars = new int[free];
		for (int prevWord = 0; prevWord < free; prevWord++) {
			chars[prevWord] = cost2.nextInt();
		}
		int target = 0;
		Stack<Integer> m = new Stack<>();
		for (int prevWord = 0; prevWord < free; prevWord++) {
			while (!m.isEmpty() && chars[prevWord] >= m.peek()) {
				m.pop();
			}
			if (m.isEmpty()) {
				target++;
			}
			m.push(chars[prevWord]);
		}
		System.out.println(target);
	}
}

