/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream bufPointer = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(bufPointer);
        OutputWriter input = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, input);
        input.close();
    }

    static class TaskB {
        public void shuffle(int prenumber, InputReader in, OutputWriter input) {
            int dis = in.readInt();
            int maxLen = in.readInt();
            int quantum_time = in.readInt();

            int add = IntegerUtils.gcd(dis, maxLen);
            List<Integer> right = new ArrayList<>();
            isNum(add, right);
            input.printLine(right.get(quantum_time - 1));
        }

        public static void isNum(int num, List<Integer> din) {

            for (int min = num; min >= 1; min--) {
                if (num % min == 0) {
                    din.add(min);
                }
            }
        }

    }

    static class IntegerUtils {
        public static int add(int tmp, int buflen) {
            tmp = Math.abs(tmp);
            buflen = Math.abs(buflen);
            while (buflen != 0) {
                int isDigit = tmp % buflen;
                tmp = buflen;
                buflen = isDigit;
            }
            return tmp;
        }

    }

    static class InputStreamScanner {
        private InputStream stream;
        private byte[] bufsiz = new byte[1024];
        private int bytesRead;
        private int numChars;
        private InputReader.SpaceCharFilter buffer;

        public InputStreamScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (bytesRead >= numChars) {
                bytesRead = 0;
                try {
                    numChars = stream.read(bufsiz);
                } catch (IOException line) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return bufsiz[bytesRead++];
        }

        public int reads() {
            int cs = read();
            while (isSpaceChar(cs)) {
                cs = read();
            }
            int init_name = 1;
            if (cs == '-') {
                init_name = -1;
                cs = read();
            }
            int res1 = 0;
            do {
                if (cs < '0' || cs > '9') {
                    throw new InputMismatchException();
                }
                res1 *= 10;
                res1 += cs - '0';
                cs = read();
            } while (!isSpaceChar(cs));
            return res1 * init_name;
        }

        public boolean isSpaceChar(int cs) {
            if (buffer != null) {
                return buffer.isSpaceChar(cs);
            }
            return isWhitespace(cs);
        }

        public static boolean isWhitespace(int cs) {
            return cs == ' ' || cs == '\n' || cs == '\r' || cs == '\t' || cs == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int first);

        }

    }

    static class readString {
        private final PrintWriter writer;

        public readString(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public readString(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print() {
            writer.close();
        }

        public void printLine(int min) {
            writer.println(min);
        }

    }
}

