public class Main {
	public static int getMod(int arg,int less) {
		while(true) {
			arg%=less;
			if(arg==0)return less;
			less%=arg;
			if(less==0)return arg;
		}
	}
	public static void main(String[] args) throws IOException{
		BufferedReader counter=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer timeCount=new StringTokenizer(counter.readLine());
		int arg=Integer.parseInt(timeCount.nextToken()),less=Integer.parseInt(timeCount.nextToken()),flag=Integer.parseInt(timeCount.nextToken());
		int ts=getMod(arg,less),end=ts;
		while(flag>1) {
			if(ts%--end==0)--flag;
		}
		System.out.println(end);
	}
}

