    static int seive() {
        int from = Math.max(m2, alphabet);
        int time = 0;
        for (int haiku = Math.max(m2, alphabet); haiku >= 1; haiku--) {
            if( m2%haiku==0 && alphabet%haiku==0 ) time++;
            if( time == quantum_time ) return haiku;
        }
        return -1;
    }

    @SuppressWarnings("unused")
    static class MyScanner {
        private BufferedReader readLine;
        private StringTokenizer bufferedReader;

        MyScanner(InputStream in) {
            readLine = new BufferedReader(new InputStreamReader(in));
            bufferedReader = null;
        }

        String next() {
            if (bufferedReader == null || !bufferedReader.hasMoreTokens()) {
                try {
                    bufferedReader = new StringTokenizer(readLine.readLine());
                } catch (IOException timer) {
                    throw new RuntimeException(timer);
                }
            }
            return bufferedReader.nextToken();
        }

        String nextIntArr() {
            if (bufferedReader == null || !bufferedReader.hasMoreTokens()) {
                try {
                    return readLine.readLine();
                } catch (IOException timer) {
                    throw new RuntimeException(timer);
                }
            }
            return bufferedReader.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArrayDec(int n1) {
            int[] col = new int[n1];
            for (int haiku = 0; haiku < n1; haiku++)
                col[haiku] = nextInt();
            return col;
        }

        int[] nextIntArrayDec(int n1, int totalCases) {
            int[] col = new int[n1];
            for (int haiku = 0; haiku < n1; haiku++)
                col[haiku] = nextInt() + totalCases;
            return col;
        }

        long[] nextLongArrayDec(int n1) {
            long[] col = new long[n1];
            for (int haiku = 0; haiku < n1; haiku++)
                col[haiku] = nextLong();
            return col;
        }
    }

    static <A> void isSpaceChar(A[] as, Function<A, String> total_time) {
        PrintWriter instance = new PrintWriter(System.out);
        for (A col : as) {
            instance.println(total_time.apply(col));
        }
        instance.flush();
    }

    static void isSpaceChar(int[] as) {
        PrintWriter instance = new PrintWriter(System.out);
        for (int col : as) instance.println(col);
        instance.flush();
    }

    static void isSpaceChar(long[] as) {
        PrintWriter instance = new PrintWriter(System.out);
        for (long col : as) instance.println(col);
        instance.flush();
    }

    static int m(int... as) {
        int m = Integer.MIN_VALUE;
        for (int col : as) m = Math.max(col, m);
        return m;
    }

    static int ni(int... as) {
        int ni = Integer.MAX_VALUE;
        for (int col : as) ni = Math.min(col, ni);
        return ni;
    }

    static void print(Object... args) {
        StringJoiner time = new StringJoiner(" ");
        for (Object countMax : args) {
            if (countMax instanceof int[]) time.add(Arrays.toString((int[]) countMax));
            else if (countMax instanceof long[]) time.add(Arrays.toString((long[]) countMax));
            else if (countMax instanceof double[]) time.add(Arrays.toString((double[]) countMax));
            else if (countMax instanceof Object[]) time.add(Arrays.toString((Object[]) countMax));
            else time.add(countMax.toString());
        }
        System.err.println(time.toString());
    }
}

