public class Main {
	public static int CardGame(int residents[], int mark) {
		int count[] = new int[residents.length];
		count[0] = 0;
		count[1] = Math.abs(residents[1] - residents[0]);
		for (int mini = 2; mini < residents.length; mini++) {
			count[mini] = Integer.MAX_VALUE;
			for (int time = 1; time <= mark; time++) {
				if (mini - time >= 0) {
					count[mini] = Math.min(Math.abs(residents[mini - time] - residents[mini]) + count[mini - time], count[mini]);
				}
			}
		}
		return count[residents.length - 1];
	}

