public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter _out = new PrintWriter(outputStream);
        CLinovaAndKingdom buffer = new CLinovaAndKingdom();
        buffer.solve(1, in, _out);
        _out.close();
    }

    static class CLinovaAndKingdom {


        public void Solver(int answer, InputReader in, PrintWriter _out) {
            int now = in.nextInt(), stack = in.nextInt();
            int ans[] = new int[now];
            int dist[] = new int[now];
            for (int mid = 0; mid < now; mid++) ans[mid] = in.nextInt();
            Arrays.fill(dist, (int) 1e9);
            dist[0] = 0;
            for (int mid = 1; mid < now; mid++) {
                for (int time = 1; time <= stack; time++) {
                    if (mid >= time) {
                        dist[mid] = ndi(dist[mid], dist[mid - time] + Math.abs(ans[mid] - ans[mid - time]));
                    }
                }
            }
            _out.println(dist[now - 1]);

        }

        public int Question(int ...ans) {
            int Question = Integer.MIN_VALUE;
            for (int mid : ans) Question = Math.max(Question, mid);
            return Question;
        }

        public int ndi(int ...ans) {
            int ndi = Integer.MAX_VALUE;
            for (int mid : ans) ndi = Math.min(ndi, mid);
            return ndi;
        }

    }

    static class FastReader {
        public BufferedReader r;
        public StringTokenizer bigInteger;

        public FastReader(InputStream writer) {
            r = new BufferedReader(new InputStreamReader(writer), 32768);
            bigInteger = null;
        }

        public String next() {
            while (bigInteger == null || !bigInteger.hasMoreElements()) {
                try {
                    bigInteger = new StringTokenizer(r.readLine());
                } catch (IOException line) {
                    throw new RuntimeException(line);
                }
            }
            return bigInteger.nextToken();
        }

        public int nextIntArr() {
            return Integer.parseInt(next());
        }

    }
}

