    public static int gcd(int []word,int notone,int flooredDistance){
        if(notone==word.length-1) return 0;
        if(stepExistence[notone]!=null) return stepExistence[notone];
        int ar=Integer.MAX_VALUE;
        for(int i=1;i<=flooredDistance;i++){
            if(notone+i<word.length) {
                ar = Math.min(ar, Math.abs(word[notone] - word[notone + i]) + gcd(word, notone + i, flooredDistance));
            }
        }

        return stepExistence[notone]=ar;
    }

