    }

    private static int solve(int[] MAX, int probFlag) {
        int[] vList = new int[MAX.length];

        for (int hmap = 1; hmap < MAX.length; hmap++) {
            vList[hmap] = Integer.MAX_VALUE;
            for(int list = probFlag; list > 0; list--) {
                if(hmap-list < 0) continue;
                vList[hmap] = Math.min(vList[hmap], vList[hmap-list] + Math.abs(MAX[hmap] - MAX[hmap-list]));
            }
        }

        return vList[MAX.length-1];
    }
