public class Main{
  public static long dist[]=new long[100001];
  public static long selectionSort(long ans[],int i,int stack){
    if(i==ans.length-1)
    {
      return 0;
    }
    if(i>ans.length-1)
    {
      return 1000000000;
    }
    if(dist[i]!=-1)
    return dist[i];
    long minF=1000000000;
    for(int dMin=i+1;dMin<=i+stack;dMin++){
      long count;
      if(dMin<=ans.length-1){
      count=Math.abs(ans[i]-ans[dMin])+selectionSort(ans,dMin,stack);
      minF=Math.min(count,minF);
      dist[i]=minF;
      }
    }
    return dist[i];
  }
  public static void main(String[] args){
    Scanner scan=new Scanner(System.in); 
    int now=scan.nextInt();
    int stack=scan.nextInt();
    long ans[]=new long[now];
    for(int i=0;i<now;i++){
    dist[i]=-1;
    ans[i]=scan.nextLong();
    }
    dist[now]=-1;
    System.out.print(selectionSort(ans,0,stack));
  }
}

