import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner ans = new Scanner(System.in);

        int distance = ans.nextInt();
        int end = ans.nextInt();
        int[] Mini = new int[distance];
        for (int mid = 0; mid < Mini.length; ++mid) {
            Mini[mid] = ans.nextInt();
        }

        System.out.println(targetInt(Mini, end));

        ans.close();
    }

    static int targetInt(int[] Mini, int end) {
        int[] start = new int[Mini.length];
        Arrays.fill(start, Integer.MAX_VALUE);
        start[0] = 0;

        for (int mid = 0; mid < start.length; ++mid) {
            for (int isAc = mid - 1; isAc >= 0 && mid - isAc <= end; --isAc) {
                start[mid] = Math.min(start[mid], start[isAc] + Math.abs(Mini[mid] - Mini[isAc]));
            }
        }

        return start[start.length - 1];
    }
}

