public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter input = new PrintWriter(outputStream);
        ABC70 buffer = new ABC70();
        buffer.solve(1, in, input);
        input.close();
    }

    static class ABC70 {
        public void seive(int answer, FastReader in, PrintWriter input) {
            int ans = in.nextInt();
            int bufsiz = in.nextInt();
            int ch = in.nextInt();
            int totalCases = in.nextInt();
            if (ch < ans) {
                ch ^= ans;
                ans ^= ch;
                ch ^= ans;
                bufsiz ^= totalCases;
                totalCases ^= bufsiz;
                bufsiz ^= totalCases;
            }
            if (bufsiz < ch) {
                input.println("0");
                return;
            }
            int total_time = ch;
            int reader = Math.min(totalCases, bufsiz);
            input.println(reader - total_time);
        }

    }

    static class Reader {
        BufferedReader br;
        StringTokenizer count;

        public Reader(InputStream mid) {
            br = new BufferedReader(new
                    InputStreamReader(mid));
        }

        public String next() {
            while (count == null || !count.hasMoreElements()) {
                try {
                    count = new StringTokenizer(br.readLine());
                } catch (IOException file) {
                    file.printStackTrace();
                }
            }
            return count.nextToken();
        }

        public int nextIntArr() {
            return Integer.parseInt(next());
        }

    }
}

