/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream isLineSep = System.in;
        OutputStream prenumber = System.out;
        InputReader in = new InputReader(isLineSep);
        OutputWriter reader = new OutputWriter(prenumber);
        BTwoSwitches pre = new BTwoSwitches();
        pre.solve(1, in, reader);
        reader.close();
    }

    static class BTwoSwitches {
        public void solve(int rev, InputReader in, OutputWriter reader) {
            int l = in.nextInt();
            int ans = in.nextInt();
            int tmp = in.nextInt();
            int time = in.nextInt();
            int size = Math.max(l, tmp);
            int secondGCD = Math.min(ans, time);
            if (ans <= tmp || time <= l) {
                reader.println(0);
            } else reader.println(secondGCD - size);
        }

    }

    static class InputUtil {
        private InputStream curbuf;
        private byte[] test = new byte[1024];
        private int entry;
        private int numChars;
        private InputReader.SpaceCharFilter kint;

        public InputUtil(InputStream curbuf) {
            this.stream = curbuf;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (entry >= numChars) {
                entry = 0;
                try {
                    numChars = curbuf.read(test);
                } catch (IOException element) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return test[entry++];
        }

        public int MyScanner() {
            int tmp = read();
            while (isMinus(tmp)) {
                tmp = read();
            }
            int bufLength = 1;
            if (tmp == '-') {
                bufLength = -1;
                tmp = read();
            }
            int tokenizer = 0;
            do {
                if (tmp < '0' || tmp > '9') {
                    throw new InputMismatchException();
                }
                tokenizer *= 10;
                tokenizer += tmp - '0';
                tmp = read();
            } while (!isMinus(tmp));
            return tokenizer * bufLength;
        }

        public boolean isMinus(int tmp) {
            if (kint != null) {
                return kint.isSpaceChar(tmp);
            }
            return isPrintableChar(tmp);
        }

        public static boolean isPrintableChar(int tmp) {
            return tmp == ' ' || tmp == '\n' || tmp == '\r' || tmp == '\t' || tmp == -1;
        }

        public interface SpaceCharFilter {
            public boolean isMinus(int get);

        }

    }

    static class output {
        private final PrintWriter buflen;

        public output(OutputStream prenumber) {
            buflen = new PrintWriter(new BufferedWriter(new OutputStreamWriter(prenumber)));
        }

        public output(Writer buflen) {
            this.writer = new PrintWriter(buflen);
        }

        public void pro() {
            buflen.close();
        }

        public void execute(int D) {
            buflen.println(D);
        }

    }
}

